import {RETIRED_GAME_IDS} from './retired.mjs';
export function isBetaEntry(game){return game?.type==='beta-local'&&game.releaseStatus==='beta-local'&&game.verified===false&&game.beta?.localOnly===true&&/^(?:gn-[0-9]+|local-slope)$/.test(game.id)&&game.url===`/arcade-beta/runtime/${game.id}/index.beta.html`;}
export function isLibraryEntry(game){return game.disabled!==true&&!RETIRED_GAME_IDS.includes(game.id)&&(isBetaEntry(game)||game.verified===true||(game.releaseStatus==='awaiting-user-gameplay'&&game.verification?.launch==='verified-stage2'));}
export const KEY='poxey-arcade-v1';
export function readState(storage,ids){ids=ids.filter(id=>!RETIRED_GAME_IDS.includes(id));try{const data=JSON.parse(storage.getItem(KEY)||'{}');return {favorites:Array.isArray(data.favorites)?[...new Set(data.favorites.filter(id=>ids.includes(id)))]:[],recent:Array.isArray(data.recent)?[...new Set(data.recent.filter(id=>ids.includes(id)))].slice(0,12):[]};}catch{return {favorites:[],recent:[]};}}
export function filterGames(games,{query='',category='All',view='Discover',favorites=[],recent=[]}={}){let result=games.filter(isLibraryEntry);if(view==='Beta games')result=result.filter(isBetaEntry);if(view==='Previously available')result=result.filter(g=>g.beta?.legacyRetained===true);if(view==='Favorites')result=result.filter(g=>favorites.includes(g.id));if(view==='Recently played')result=recent.map(id=>result.find(g=>g.id===id)).filter(Boolean);return result.filter(g=>(category==='All'||category==='Beta'&&isBetaEntry(g)||g.category===category)&&(g.name+' '+g.category).toLowerCase().includes(query.trim().toLowerCase()));}

